const profile = $json.body;

const studentData = {
  personalInfo: {
    name: profile.name,
    email: profile.email,
    phone: profile.phone,
    address: profile.address,
    linkedin: profile.linkedin
  },
  academics: {
    age: profile.age,
    educationLevel: profile.education_level,
    gradingSystem: profile.grading_system,
    academicScore: profile.academic_score,
    standardizedTest: profile.standardized_test,
    testScore: profile.test_score
  },
  preferences: {
    targetCountries: profile.target_countries || [],
    studyLevel: profile.study_level,
    budgetMin: profile.budget_min,
    budgetMax: profile.budget_max,
    scholarshipInterest: profile.scholarship_interest,
    subjects: profile.subjects || [],
    extracurriculars: profile.extracurriculars || [],
    careerGoals: profile.career_goals
  },
  experience: {
    organization: profile.organization,
    designation: profile.designation,
    bio: profile.bio,
    skills: profile.skills || []
  }
};

return { studentData };

const data = $json.studentData;

const prompt = `You are an expert student counselor with 20 years of experience. Based on this student profile, write a personalized, encouraging message (3-4 paragraphs). Address their academics, goals, and university search strategy with warmth and professionalism.

STUDENT: ${data.personalInfo.name}
AGE: ${data.academics.age}
ACADEMIC SCORE: ${data.academics.academicScore} (${data.academics.gradingSystem})
TEST: ${data.academics.standardizedTest} (${data.academics.testScore})
GOALS: ${data.preferences.careerGoals || 'Not specified'}
SUBJECTS: ${data.preferences.subjects.join(', ')}
TARGET COUNTRIES: ${data.preferences.targetCountries.join(', ')}
BUDGET: $${data.preferences.budgetMin}-$${data.preferences.budgetMax}

Write an encouraging, personalized counselor message.`;

return { prompt };

const response = $json.body;

if (!response.candidates || response.candidates.length === 0) {
  throw new Error('No response from Gemini API');
}

const counselorMessage = response.candidates[0].content.parts[0].text;

return { counselorMessage };

const matchedUniversities = {
  safe: [
    { name: "University of California, Berkeley", country: "USA", city: "Berkeley", score: 85, acceptance_rate: 15 },
    { name: "Stanford University", country: "USA", city: "Stanford", score: 82, acceptance_rate: 3 },
    { name: "MIT", country: "USA", city: "Cambridge", score: 88, acceptance_rate: 4 },
    { name: "Harvard University", country: "USA", city: "Cambridge", score: 86, acceptance_rate: 3 },
    { name: "Yale University", country: "USA", city: "New Haven", score: 84, acceptance_rate: 4 }
  ],
  target: [
    { name: "University of Toronto", country: "Canada", city: "Toronto", score: 72, acceptance_rate: 20 },
    { name: "University of British Columbia", country: "Canada", city: "Vancouver", score: 70, acceptance_rate: 23 },
    { name: "McGill University", country: "Canada", city: "Montreal", score: 71, acceptance_rate: 24 },
    { name: "University of Waterloo", country: "Canada", city: "Waterloo", score: 68, acceptance_rate: 30 },
    { name: "University of Alberta", country: "Canada", city: "Edmonton", score: 65, acceptance_rate: 32 }
  ],
  dream: [
    { name: "Oxford University", country: "UK", city: "Oxford", score: 55, acceptance_rate: 2 },
    { name: "Cambridge University", country: "UK", city: "Cambridge", score: 54, acceptance_rate: 2 },
    { name: "Imperial College London", country: "UK", city: "London", score: 58, acceptance_rate: 8 },
    { name: "ETH Zurich", country: "Switzerland", city: "Zurich", score: 52, acceptance_rate: 5 },
    { name: "National University of Singapore", country: "Singapore", city: "Singapore", score: 60, acceptance_rate: 25 }
  ]
};

return { matchedUniversities };

return {
  timestamp: new Date().toISOString(),
  studentEmail: $json.studentData.personalInfo.email,
  status: 'success',
  counselorMessageLength: $json.counselorMessage.length,
  matchCount: $json.matchedUniversities.safe.length + $json.matchedUniversities.target.length + $json.matchedUniversities.dream.length,
  message: 'Counselor email sent successfully'
};
